<?php
declare(strict_types=1);
namespace Sinaesta\Shared\Http\Middleware;
use PDO; use Sinaesta\Shared\Http\HttpException; use Sinaesta\Shared\Http\Request; use Sinaesta\Shared\Http\Response;
final readonly class RateLimitMiddleware { public function __construct(private PDO $pdo, private string $scope, private int $limit, private int $windowSeconds) {} public function __invoke(Request $request, callable $next): Response { $key=hash('sha256',$this->scope.'|'.$request->ip); $this->pdo->beginTransaction(); try { $select=$this->pdo->prepare('SELECT id, hits, window_started_at FROM rate_limits WHERE rate_key=:key FOR UPDATE'); $select->execute(['key'=>$key]); $row=$select->fetch(); $now=time(); if (!$row || strtotime((string)$row['window_started_at']) <= $now-$this->windowSeconds) { $stmt=$this->pdo->prepare('INSERT INTO rate_limits (rate_key, scope, hits, window_started_at, expires_at) VALUES (:key,:scope,1,NOW(),DATE_ADD(NOW(), INTERVAL :seconds SECOND)) ON DUPLICATE KEY UPDATE hits=1,window_started_at=NOW(),expires_at=DATE_ADD(NOW(), INTERVAL :seconds2 SECOND)'); $stmt->execute(['key'=>$key,'scope'=>$this->scope,'seconds'=>$this->windowSeconds,'seconds2'=>$this->windowSeconds]); } else { if ((int)$row['hits'] >= $this->limit) { $this->pdo->rollBack(); throw new HttpException(429,'Terlalu banyak permintaan. Silakan coba lagi nanti.'); } $stmt=$this->pdo->prepare('UPDATE rate_limits SET hits=hits+1 WHERE id=:id'); $stmt->execute(['id'=>$row['id']]); } $this->pdo->commit(); } catch (\Throwable $e) { if ($this->pdo->inTransaction()) $this->pdo->rollBack(); throw $e; } return $next($request); } }
